wildcard_matching.brute:
brute_force(s, p):
    if p is empty: return s is empty
    if p[0] == '*':
        if brute_force(s, rest of p): return true   (star matches nothing)
        if s is not empty and brute_force(rest of s, p): return true   (star swallows one more char)
        return false
    if s is empty: return false
    if p[0] != s[0] and p[0] != '?': return false
    return brute_force(rest of s, rest of p)

wildcard_matching.optimal:
i = 0, j = 0   (positions in s and p)
star = -1, match = 0   (last '*' in p, and where in s it started matching)
while i < size of s:
    if j < size of p and (p[j] == s[i] or p[j] == '?'):
        i += 1, j += 1
    else if j < size of p and p[j] == '*':
        star = j, match = i
        j += 1   (the star matches nothing for now)
    else if star != -1:
        match += 1   (that star swallows one more char and we retry)
        i = match, j = star + 1
    else:
        return false
while j < size of p and p[j] == '*': j += 1   (leftover stars match the empty string)
return j == size of p

find_longest_awesome_substring.brute:
best = 0
for each starting index i:
    counts = 10 zeros
    for each j from i to the end:   (the substring s[i..j])
        counts[s[j]] += 1
        odd = how many of the 10 counts are odd
        if odd <= 1: best = max(best, j - i + 1)
return best

find_longest_awesome_substring.optimal:
first_seen = dict parity-mask -> earliest prefix index, with first_seen[0] = -1
mask = 0, best = 0
for each j, digit c in s:
    mask = mask XOR bit c   (flip this digit's parity bit)
    if mask in first_seen: best = max(best, j - first_seen[mask])   (all counts in between are even)
    for each digit d from 0 to 9:   (exactly one digit odd in between)
        partner = mask XOR bit d
        if partner in first_seen: best = max(best, j - first_seen[partner])
    if mask not in first_seen: first_seen[mask] = j   (keep only the earliest)
return best

maximum_xor_with_an_element_from_array.brute:
answer = empty list
for each query (x, m):
    best = -1
    for each value in nums:   (re-filter and re-scan nums for every query)
        if value <= m: best = max(best, x XOR value)
    append best to answer
return answer

